//! The vehicle plant from `models/hopper_6dof.slx` (CONTROLLER=fsw), as
//! generated by the hopper repo's
//! `sims/hopper_6dof_sizer/fsw_bridge/build_plant_c.m`, for flight software to
//! fly.
//!
//! The plant steps at a fixed 1 ms ([`STEP`]); the flight software
//! commands it every [`FSW_PERIOD`] (10 ms). One control period goes:
//!
//! 1. [`Plant::state`] at the period's start time t_k,
//! 2. the flight software computes its command and calls [`Plant::run_period`],
//!    which advances the plant to t_k + [`FSW_PERIOD`].
//!
//! The harness takes the new command one plant step after t_k: the
//! flight software's compute latency. `fswWorkspace.m` sets the same in
//! Simulink, so a replay there matches this code exactly
//! (`fsw_bridge/verify_plant_c.m` in the hopper repo).
//!
//! The generated code is a single global instance, so only one [`Plant`]
//! can exist at a time.

use std::{
    ffi::CStr,
    sync::atomic::{AtomicBool, Ordering},
    time::Duration,
};

include!(concat!(env!("OUT_DIR"), "/plant_consts.rs"));

/// [thrust N, TVC pitch rad, TVC yaw rad, RCS (roll) torque N m]
pub type Command = [f64; 4];

/// Where each reading is in [`Sensors::meas`] and each sensor's flag and time in
/// [`Sensors::valid`] and [`Sensors::stamp`]: hopper's `sensor_layout.m`, checked
/// against `plant.json` when the plant is built.
pub mod layout {
    use std::ops::Range;

    /// IMU specific force, body axes, m/s^2
    pub const ACCEL: Range<usize> = 0..3;
    /// IMU body rates, rad/s
    pub const GYRO: Range<usize> = 3..6;
    /// Barometric altitude above the pad, m
    pub const BARO: usize = 6;
    /// LiDAR beam ranges 1 to 4, m
    pub const LIDAR: Range<usize> = 7..11;
    /// GPS antenna 1 position, NED from the pad origin, m
    pub const GPS_POS: Range<usize> = 11..14;
    /// GPS fix type (3 = 3D)
    pub const GPS_FIX: usize = 14;
    /// Satellites used
    pub const GPS_SATS: usize = 15;
    /// Magnetic field, body axes, uT
    pub const MAG: Range<usize> = 17..20;
    /// GPS velocity, NED, m/s
    pub const GPS_VEL: Range<usize> = 20..23;

    /// Sensor index in `valid` and `stamp`
    pub const S_IMU: usize = 0;
    pub const S_BARO: usize = 1;
    /// LiDAR beams 1 to 4
    pub const S_LIDAR: Range<usize> = 2..6;
    pub const S_GPS: usize = 6;
    pub const S_MAG: usize = 7;
}

/// What the Sensors block puts out, after its fault gates: what the flight
/// computer's drivers would read.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Sensors {
    /// The 26 measurements, see [`layout`]
    pub meas: [f64; 26],
    /// Whether each of the 9 sensors has a valid reading
    pub valid: [bool; 9],
    /// The time each sensor last took a sample, s: it changes with each new
    /// sample, and holds in between
    pub stamp: [f64; 9],
}

/// [pos NED m (3), vel NED m/s (3), body rates rad/s (3), quaternion q0..q3]:
/// the truth state the harness's own controller flies on
pub type State = [f64; 13];

#[cfg(not(hopper_plant_stub))]
extern "C" {
    fn plant_initialize();
    fn plant_reset();
    fn plant_output();
    fn plant_update();
    fn plant_terminate();
    fn plant_time() -> f64;
    fn plant_stop_requested() -> i32;
    fn plant_error() -> *const std::os::raw::c_char;
    fn plant_set_u(u: *const f64);
    fn plant_get_x(x: *mut f64);
    fn plant_get_sensors(meas: *mut f64, valid: *mut f64, stamp: *mut f64) -> i32;
}

/// Built without HOPPER_PLANT_CODE: no plant. `Plant::new` fails first, so
/// none of these is ever called.
#[cfg(hopper_plant_stub)]
#[allow(clippy::missing_safety_doc)]
mod stub {
    use std::os::raw::c_char;
    pub unsafe fn plant_initialize() {}
    pub unsafe fn plant_reset() {}
    pub unsafe fn plant_output() {}
    pub unsafe fn plant_update() {}
    pub unsafe fn plant_terminate() {}
    pub unsafe fn plant_time() -> f64 {
        0.0
    }
    pub unsafe fn plant_stop_requested() -> i32 {
        0
    }
    pub unsafe fn plant_error() -> *const c_char {
        std::ptr::null()
    }
    pub unsafe fn plant_set_u(_: *const f64) {}
    pub unsafe fn plant_get_x(_: *mut f64) {}
    pub unsafe fn plant_get_sensors(_: *mut f64, _: *mut f64, _: *mut f64) -> i32 {
        0
    }
}
#[cfg(hopper_plant_stub)]
use stub::*;

static TAKEN: AtomicBool = AtomicBool::new(false);

/// A `Plant` has been created before in this process, so the generated
/// globals are no longer in their start-up state.
static INITIALIZED: AtomicBool = AtomicBool::new(false);

#[derive(Debug, Clone, PartialEq)]
pub enum Error {
    /// Another [`Plant`] exists (the generated code has one global instance)
    InUse,
    /// Built without the generated plant (HOPPER_PLANT_CODE unset)
    NotBuilt,
    /// The generated code reported an error (rtmGetErrorStatus)
    Model(String),
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Error::InUse => write!(f, "the plant is already in use"),
            Error::NotBuilt => write!(
                f,
                "built without the plant: set HOPPER_PLANT_CODE to build_plant_c's output and rebuild"
            ),
            Error::Model(e) => write!(f, "plant model error: {e}"),
        }
    }
}

impl std::error::Error for Error {}

/// What one control period did
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Period {
    /// Plant time at the end of the period, s
    pub time: f64,
    /// The harness's touchdown stop fired during the period (or before)
    pub touchdown: bool,
}

/// The plant at a point in time. Created at t = 0 on the pad, also when an
/// earlier `Plant` in the same process has flown and been dropped.
pub struct Plant {
    steps_per_period: u32,
    /// outputs at the current time have been computed
    fresh: bool,
}

impl Plant {
    /// Initializes the plant at t = 0, with a zero command.
    pub fn new() -> Result<Self, Error> {
        if cfg!(hopper_plant_stub) {
            return Err(Error::NotBuilt);
        }
        if TAKEN.swap(true, Ordering::AcqRel) {
            return Err(Error::InUse);
        }
        // SAFETY: TAKEN guarantees no other Plant uses the global instance
        unsafe {
            if INITIALIZED.swap(true, Ordering::AcqRel) {
                // The generated initialize() leaves the model's time, states
                // and touchdown flag alone, so after an earlier Plant it
                // would carry them over. A full reset gives t = 0 again.
                plant_reset();
            } else {
                plant_initialize();
            }
        }
        let plant = Plant {
            steps_per_period: (FSW_PERIOD / STEP).round() as u32,
            fresh: false,
        };
        plant.check()?;
        Ok(plant)
    }

    /// Back to t = 0 on the pad, exactly as after [`Plant::new`]: time,
    /// states and the touchdown flag all start over.
    pub fn reset(&mut self) -> Result<(), Error> {
        // SAFETY: self owns the global instance
        unsafe { plant_reset() };
        self.fresh = false;
        self.check()
    }

    /// Plant time, s
    pub fn time(&self) -> f64 {
        // SAFETY: self owns the global instance
        unsafe { plant_time() }
    }

    /// Plant time as a Duration since t = 0
    pub fn elapsed(&self) -> Duration {
        Duration::from_secs_f64(self.time().max(0.0))
    }

    /// Truth state at the current time.
    pub fn state(&mut self) -> Result<State, Error> {
        self.outputs()?;
        let mut x = [0.0; 13];
        // SAFETY: x has 13 doubles; self owns the global instance
        unsafe { plant_get_x(x.as_mut_ptr()) };
        Ok(x)
    }

    /// Whether the harness's touchdown stop has fired. The plant keeps
    /// stepping if asked; what happens after touchdown is the caller's call.
    pub fn touchdown(&self) -> bool {
        // SAFETY: self owns the global instance
        unsafe { plant_stop_requested() != 0 }
    }

    /// Applies `u` and advances one control period ([`FSW_PERIOD`]). The
    /// harness takes `u` one plant step into the period.
    pub fn run_period(&mut self, u: &Command) -> Result<Period, Error> {
        // SAFETY: u has 4 doubles; self owns the global instance
        unsafe { plant_set_u(u.as_ptr()) };
        for _ in 0..self.steps_per_period {
            self.outputs()?;
            // SAFETY: self owns the global instance
            unsafe { plant_update() };
            self.fresh = false;
            self.check()?;
        }
        Ok(Period {
            time: self.time(),
            touchdown: self.touchdown(),
        })
    }

    /// Sets the command the plant takes from the next step on.
    pub fn set_command(&mut self, u: &Command) {
        // SAFETY: u has 4 doubles; self owns the global instance
        unsafe { plant_set_u(u.as_ptr()) };
    }

    /// Advances one plant step ([`STEP`]) with the command last set.
    /// [`run_period`](Plant::run_period) is [`FSW_PERIOD`] / [`STEP`] of these.
    pub fn step(&mut self) -> Result<Period, Error> {
        self.outputs()?;
        // SAFETY: self owns the global instance
        unsafe { plant_update() };
        self.fresh = false;
        self.check()?;

        Ok(Period {
            time: self.time(),
            touchdown: self.touchdown(),
        })
    }

    /// The Sensors block's outputs at the current time, or `None` for a plant
    /// built without them ([`HAS_SENSORS`]).
    pub fn sensors(&mut self) -> Result<Option<Sensors>, Error> {
        if !HAS_SENSORS {
            return Ok(None);
        }

        self.outputs()?;

        let mut meas = [0.0; 26];
        let mut valid = [0.0; 9];
        let mut stamp = [0.0; 9];

        // SAFETY: the arrays have 26, 9 and 9 doubles; self owns the instance
        let present =
            unsafe { plant_get_sensors(meas.as_mut_ptr(), valid.as_mut_ptr(), stamp.as_mut_ptr()) };

        Ok((present != 0).then(|| Sensors {
            meas,
            valid: valid.map(|v| v != 0.0),
            stamp,
        }))
    }

    /// Plant steps per control period
    pub fn steps_per_period(&self) -> u32 {
        self.steps_per_period
    }

    fn outputs(&mut self) -> Result<(), Error> {
        if !self.fresh {
            // SAFETY: self owns the global instance
            unsafe { plant_output() };
            self.fresh = true;
            self.check()?;
        }
        Ok(())
    }

    fn check(&self) -> Result<(), Error> {
        // SAFETY: the string, if any, is a static C string in the generated
        // code
        let e = unsafe { plant_error() };
        if e.is_null() {
            Ok(())
        } else {
            Err(Error::Model(
                unsafe { CStr::from_ptr(e) }.to_string_lossy().into_owned(),
            ))
        }
    }
}

impl Drop for Plant {
    fn drop(&mut self) {
        // SAFETY: self owns the global instance
        unsafe { plant_terminate() };
        TAKEN.store(false, Ordering::Release);
    }
}
